query:
query IssuesTimeline(
	$filterInput: [FilterInput!]
	$timeFrame: IssueTimeFrame
) {
	issuesTimeline(filterInput: $filterInput, timeFrame: $timeFrame) {
		issuesDataPoints {
			fromDate
			toDate
			values {
				openLow
				openMedium
				openHigh
				openCritical
				openTotal
			}
		}
		scope
	}
}
